/**
 * Historic sites: monuments, ruins and archaeological sites in
 * src/data/sites.json, with the states and peoples that held the ground they
 * stand on in every map snapshot since they were made.
 *
 * siteRulers.json is generated by scripts/build-city-rulers.mts alongside the
 * city data. Re-run that script after editing sites.json. Corrections to it
 * live in src/data/siteRulerFixes.ts.
 */
import SITES from "@/data/sites.json";
import RULERS from "@/data/siteRulers.json";
import { SITE_RULER_FIXES } from "@/data/siteRulerFixes";
import { CITY_LIST, applyRulerFixes, withLinks, type City, type RulerSpan } from "@/lib/cityHistory";

export interface Site {
  slug: string;
  name: string;
  /** Modern country, named as in cities.json. */
  country: string;
  lat: number;
  lng: number;
  /** Rough year the site was built, made or first settled (negative = BCE). */
  built: number;
  wikidataId: string;
}

export const SITE_LIST: readonly Site[] = [...(SITES as Site[])].sort((a, b) => a.name.localeCompare(b.name));

export function getSite(slug: string): Site | undefined {
  return SITE_LIST.find((s) => s.slug === slug);
}

/**
 * Who held the site, oldest first, starting with the snapshot that was
 * current when it was built (its start clipped to the build year).
 */
export function siteRulersOf(site: Site): RulerSpan[] {
  const raw = applyRulerFixes((RULERS as Record<string, RulerSpan[]>)[site.slug] ?? [], SITE_RULER_FIXES[site.slug]);
  const spans = raw.flatMap(withLinks).filter((s) => s.to === null || s.to > site.built);
  if (spans[0] && spans[0].from < site.built) spans[0] = { ...spans[0], from: site.built };
  // A site the maps never draw inside any state gets no timeline.
  return spans.some((s) => s.name) ? spans : [];
}

/** "about 2600 BCE", "about 1450 CE". */
export function builtLabel(year: number): string {
  return year < 0 ? `about ${Math.abs(year) >= 10000 ? Math.abs(year).toLocaleString("en-US") : -year} BCE` : `about ${year} CE`;
}

function distanceKm(a: { lat: number; lng: number }, b: { lat: number; lng: number }): number {
  const rad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * rad;
  const dLng = (b.lng - a.lng) * rad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLng / 2) ** 2;
  return 2 * 6371 * Math.asin(Math.sqrt(h));
}

/** The closest other sites, nearest first. */
export function nearbySites(point: { slug?: string; lat: number; lng: number }, count = 6): Site[] {
  return SITE_LIST.filter((s) => s.slug !== point.slug)
    .map((s) => ({ s, d: distanceKm(point, s) }))
    .sort((x, y) => x.d - y.d)
    .slice(0, count)
    .map((x) => x.s);
}

/** Sites within `km` of a city, nearest first (for the city pages). */
export function sitesNear(city: City, km = 150): Site[] {
  return SITE_LIST.map((s) => ({ s, d: distanceKm(city, s) }))
    .filter((x) => x.d <= km)
    .sort((x, y) => x.d - y.d)
    .map((x) => x.s);
}

/** The cities closest to a site. */
export function citiesNear(site: Site, count = 4): City[] {
  return CITY_LIST.map((c) => ({ c, d: distanceKm(site, c) }))
    .sort((x, y) => x.d - y.d)
    .slice(0, count)
    .map((x) => x.c);
}

let siteIndex: Map<string, Site[]> | null = null;

/** Sites whose timeline links to /place/{slug}, alphabetically. */
export function sitesHeldBy(slug: string): Site[] {
  if (!siteIndex) {
    siteIndex = new Map();
    for (const site of SITE_LIST) {
      const held = new Set(siteRulersOf(site).flatMap((s) => (s.href ? [s.href] : [])));
      for (const href of held) {
        const key = href.replace("/place/", "");
        siteIndex.set(key, [...(siteIndex.get(key) ?? []), site]);
      }
    }
  }
  return siteIndex.get(slug) ?? [];
}
